examples:
#include <dt-bindings/gpio/gpio.h>

spi {
  #address-cells = <1>;
  #size-cells = <0>;

  adc@0 {
    compatible = "adi,ad4134";
    reg = <0>;

    spi-max-frequency = <1000000>;

    reset-gpios = <&gpio0 86 GPIO_ACTIVE_LOW>;

    clocks = <&sys_clk>;
    clock-names = "sys_clk";

    dmas = <&rx_dma 0>;
    dma-names = "rx";

    pwms = <&ad4134_odr_generator 0 0>;
    pwm-names = "odr_pwm";

    avdd5-supply = <&avdd5>;
    avdd1v8-supply = <&avdd1v8>;
    iovdd-supply = <&iovdd>;
    refin-supply = <&refin>;

    adi,spi-engine = <&ad4134_spi_engine>;
  };
};
